    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Find the shortest string to minimize candidate substrings
    String shortest = null;
    int minLen = Integer.MAX_VALUE;
    for (String s : strings) {
        if (s == null) {
            return 0;
        }
        if (s.length() < minLen) {
            minLen = s.length();
            shortest = s;
        }
    }
    if (minLen == 0) {
        return 0;
    }

    int left = 1;
    int right = minLen;
    int best = 0;

    while (left <= right) {
        int mid = (left + right) >>> 1;
        boolean found = false;
        // Enumerate all substrings of length mid from the shortest string
        for (int i = 0; i + mid <= shortest.length(); i++) {
            String sub = shortest.substring(i, i + mid);
            String rev = new StringBuilder(sub).reverse().toString();
            boolean ok = true;
            for (String other : strings) {
                if (other == null) {
                    ok = false;
                    break;
                }
                if (other.indexOf(sub) >= 0 || other.indexOf(rev) >= 0) {
                    continue;
                } else {
